*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_35", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "language" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("language")) === 'english'); } }, { id: "c_otherwise_38", fn: function(){ return (!((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "language" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("language")) === 'english'))); } }, { id: "if_modYn", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "modYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("modYn"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "modYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("modYn")))).length === 0)); } }, { id: "if_publDdtm", fn: function(){ return (!(String(((() => { throw new Error("unresolved:data:" + "data.publDdtm"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "data.publDdtm"); })())).length === 0)); } }, { id: "if_requestedAcptNo", fn: function(){ return ((dma_vos.get("requestedAcptNo") ?? (() => { throw new Error("unresolved:" + "vos.requestedAcptNo"); })()) === (() => { throw new Error("unresolved:data:" + "data.acptNo"); })()); } }, { id: "if_requestedAcptNo", fn: function(){ return ((String(((dma_vos.get("requestedDocNo") ?? (() => { throw new Error("unresolved:" + "vos.requestedDocNo"); })())) == null ? '' : ((dma_vos.get("requestedDocNo") ?? (() => { throw new Error("unresolved:" + "vos.requestedDocNo"); })()))).length === 0)); } }, { id: "c_otherwise_50", fn: function(){ return (!(((String(((dma_vos.get("requestedDocNo") ?? (() => { throw new Error("unresolved:" + "vos.requestedDocNo"); })())) == null ? '' : ((dma_vos.get("requestedDocNo") ?? (() => { throw new Error("unresolved:" + "vos.requestedDocNo"); })()))).length === 0)))); } }, { id: "if_requestedDocNo", fn: function(){ return ((dma_vos.get("requestedDocNo") ?? (() => { throw new Error("unresolved:" + "vos.requestedDocNo"); })()) === (() => { throw new Error("unresolved:data:" + "data.docNo"); })()); } }, { id: "if_mainTextList", fn: function(){ return (!(String(((dma_vos.get("mainTextList") ?? (() => { throw new Error("unresolved:" + "vos.mainTextList"); })())) == null ? '' : ((dma_vos.get("mainTextList") ?? (() => { throw new Error("unresolved:" + "vos.mainTextList"); })()))).length === 0)); } }, { id: "c_when_67", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "language" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("language")) === 'english'); } }, { id: "c_otherwise_70", fn: function(){ return (!((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "language" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("language")) === 'english'))); } }, { id: "c_when_74", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "modYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("modYn"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "modYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("modYn")))).length === 0)); } }, { id: "c_otherwise_78", fn: function(){ return (!((!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "modYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("modYn"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "modYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("modYn")))).length === 0)))); } }, { id: "if_publDdtm_2", fn: function(){ return (!(String(((() => { throw new Error("unresolved:data:" + "data.publDdtm"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "data.publDdtm"); })())).length === 0)); } }, { id: "if_attachedDocList", fn: function(){ return (!(String(((dma_vos.get("attachedDocList") ?? (() => { throw new Error("unresolved:" + "vos.attachedDocList"); })())) == null ? '' : ((dma_vos.get("attachedDocList") ?? (() => { throw new Error("unresolved:" + "vos.attachedDocList"); })()))).length === 0)); } }, { id: "txt_p94", fn: function(){ return ((dma_vos.get("requestedFormProcsCd") ?? (() => { throw new Error("unresolved:" + "vos.requestedFormProcsCd"); })()) === '106'); } }, { id: "c_otherwise_95", fn: function(){ return (!(((dma_vos.get("requestedFormProcsCd") ?? (() => { throw new Error("unresolved:" + "vos.requestedFormProcsCd"); })()) === '106'))); } }, { id: "c_when_91", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.langTpCd !== "undefined" && scwin.langTpCd !== null ? scwin.langTpCd : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "langTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("langTpCd")) === '1'); } }, { id: "c_otherwise_97", fn: function(){ return (!((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.langTpCd !== "undefined" && scwin.langTpCd !== null ? scwin.langTpCd : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "langTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("langTpCd")) === '1'))); } }, { id: "txt_p99", fn: function(){ return ((dma_vos.get("requestedFormProcsCd") ?? (() => { throw new Error("unresolved:" + "vos.requestedFormProcsCd"); })()) === '070' ||(dma_vos.get("requestedFormProcsCd") ?? (() => { throw new Error("unresolved:" + "vos.requestedFormProcsCd"); })()) === '120'); } }, { id: "txt_p101", fn: function(){ return ((dma_vos.get("requestedFormProcsCd") ?? (() => { throw new Error("unresolved:" + "vos.requestedFormProcsCd"); })()) === '111'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_27", entity: "dlt_vosMainTextList", countIds: [], cells: [{ childId: "option_53", fn: function (v, i) { return String(v("docNo")); } }, { childId: "__rc1", fn: function (v, i) { return String(i + 1); } }] },
        { genId: "c_foreach_65", entity: "dlt_vosAttachedDocList", countIds: [], cells: [{ childId: "__rc2", fn: function (v, i) { return " " + String(i + 1); } }, { childId: "option_82", fn: function (v, i) { return String(v("docNo")); } }, { childId: "__rc3", fn: function (v, i) { return String(i + 1); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("comAbbrv")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = function () {
    /* sdd-asis-lifecycle:begin init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const formProcsCd = $c.util.getComponent('ipt_reqFormProcsCd').getValue();
    if (formProcsCd != null && (formProcsCd === "070" || formProcsCd === "111" || formProcsCd === "120")) {
        $("section.contents").removeClass("top70");
        $("section.contents").addClass("top150");
    }
    const langTpCd = $c.util.getComponent('ipt_langTpCd').getValue();
    if (langTpCd === "1") {
        $("section.contents").removeClass("top70");
        $("section.contents").addClass("top150");
    }
    scwin.search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        let btn_close_t = 0;
        scwin.fnTocInit();
        btn_close_t = parseInt($('section.toc-wrapper a.btn-close').css("top"));
        scwin.init();
        scwin.fnTocResize();
        $(window).resize(function() {
                scwin.fnTocResize();
        });
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst90002.onpageload' }); }
};

// [A] 초기 목록 미해결 — jlddst90002: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst90002.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.slc_mainDocId_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_mainDocId_onchange = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_mainDocId_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.changeDoc(selfVar, 'mainDoc'); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst90002.slc_mainDocId_onchange' }); }
};

