scwin.slc_attachedDocId_onchange = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_attachedDocId_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.changeDoc(selfVar, 'attachedDoc'); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst90002.slc_attachedDocId_onchange' }); }
};

/**
 * @event
 * @name scwin.btn_printDocument_onclick
 * @author Inswave
