 * @hidden N
*/
scwin.btn_printDocument_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_printDocument_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.printDocument(); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst90002.btn_printDocument_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fnTocInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnTocInit = function () {
    /* sdd-asis-lifecycle:begin fnTocInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('#toc').attr("allowTransparency", "true");
    $('section.toc-wrapper a.btn-close').bind('click', function() {
            $('section.toc-wrapper').addClass("hide");
            $('div.layer-opener-wrapper').addClass("active");
            (($c.util.getComponent('doc')) && ($c.util.getComponent('doc')).addClass ? ($c.util.getComponent('doc')).addClass("active") : console.error('[sdd] addClass 미지원 컴포넌트: doc'));
            setTimeout(function(){ scwin.fnTocResize() }, 100);
    });
    $('div.layer-opener-wrapper a.btn-open').bind('click', function() {
            $('section.toc-wrapper').removeClass("hide");
            $('div.layer-opener-wrapper').removeClass("active");
            (($c.util.getComponent('doc')) && ($c.util.getComponent('doc')).removeClass ? ($c.util.getComponent('doc')).removeClass("active") : console.error('[sdd] removeClass 미지원 컴포넌트: doc'));
            setTimeout(function(){ scwin.fnTocResize() }, 100);
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnTocResize
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnTocResize = function () {
    /* sdd-asis-lifecycle:begin fnTocResize — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const x = $("section.contents").offset();
    const tocTdWidth = $(".openToc").width() + 30;
    const bh = $("body").height();
    const bw = $("body").width();
    const h = bh - 265;
    $("#toc").height(h);
    $("#docViewFrm").height(h + 28);
    $("#docViewFrm").width(bw - tocTdWidth);
    $('div.layer-opener-wrapper a.btn-open').height(h - 61);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param docNo
 * @returns
 * @hidden N
*/
scwin.search = function (docNo) {
    /* sdd-asis-lifecycle:begin search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (docNo == null || docNo === 'undefined' || docNo === '') {
        val = $c.util.getComponent('slc_mainDocId').getValue();
    } else {
        val = docNo;
    }
    $c.util.getComponent('ipt_docNo').setValue(val);
    $("#docpathsearchForm").submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setPath
 * @author Inswave
 * @date 2026. 09. 29
 * @param tocLocPath docLocPath docServerPath
 * @returns
 * @hidden N
*/
scwin.setPath = function (tocLocPath, docLocPath, docServerPath) {
    /* sdd-asis-lifecycle:begin setPath — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const url = location.href;
    if (url.indexOf("https://") != -1) {
        tocLocPath = tocLocPath.replace("http://", "https://");
        docLocPath = docLocPath.replace("http://", "https://");
    }
    if (url.indexOf("/idev") != -1) {
        tocLocPath = tocLocPath.replace("/dev", "/idev");
        docLocPath = docLocPath.replace("/dev", "/idev");
    }
    if (docLocPath === "") {
        return;
    }
    if (tocLocPath === "") {
        $('section.toc-wrapper a.btn-close').click();
        document.toc.location.href = "/common/noToc.htm";
    } else {
        document.toc.location.href = tocLocPath;
        (($c.util.getComponent('toc')) && ($c.util.getComponent('toc')).setSrc ? ($c.util.getComponent('toc')).setSrc(tocLocPath) : console.error('[sdd] setSrc 미지원 컴포넌트: toc'));
        $("#toc").load(function() {
                $("#toc").contents().find('link').attr('href', '/external/dart_toc.css');
                $("#toc").contents().find("a").attr("target", "docViewFrm");
        });
    }
    document.docViewFrm.location.href = docLocPath;
    $("#docViewFrm").load(function() {
            if ($("#docViewFrm").contents().find('link').length > 0) {
                if ($("#docViewFrm").contents().find('link').attr('href').indexOf('/external/report_xml.css') != -1) {
                    $("#docViewFrm").contents().find('link').attr('href', '/external/report_xml.css');
                } else {
                    if ($("#docViewFrm").contents().find('link').attr('href').indexOf('/external/xforms.css') != -1) {
                        $("#docViewFrm").contents().find('link').attr('href', '/external/xforms.css');
                    } else {
                        if ($("#docViewFrm").contents().find('link').attr('href').indexOf('/notoSans.css') != -1) {
                            $("#docViewFrm").contents().find('link').attr('href', '/esg/notoSans.css');
                        }
                    }
                }
            }
    });
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('docLocPath', docLocPath) : console.warn('[sdd] hiddenStore 부재: docLocPath'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('docpath', docServerPath + ".htm") : console.warn('[sdd] hiddenStore 부재: docpath'));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeDoc
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj docGubun
 * @returns
 * @hidden N
*/
scwin.changeDoc = function (obj, docGubun) {
    /* sdd-asis-lifecycle:begin changeDoc — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const searchForm = (document.searchForm || { elements: [] });
    const docNo = obj.getValue();
    if (docNo != null && docNo !== "") {
        const mainDoc = $c.util.getComponent('slc_mainDocId');
        const attachedDoc = $c.util.getComponent('slc_attachedDocId');
        if (docGubun === "mainDoc") {
            document.attachedDoc.options[0].selected = true;
        } else {
            if (docGubun === "attachedDoc") {
                document.mainDoc.options[0].selected = true;
            }
        }
        scwin.search(docNo);
    }
    /* sdd-asis-lifecycle:end */
};


